public static class Amc {
 public static readonly string[] Cycles=["daily","alternate-days","weekly","monthly","quarterly","six-monthly","yearly"];
 public static DateOnly AddMonth(DateOnly date,int months){int total=date.Year*12+date.Month-1+months,year=total/12,month=total%12+1;return new DateOnly(year,month,Math.Min(date.Day,DateTime.DaysInMonth(year,month)));}
 public static DateOnly At(DateOnly start,string cycle,int index)=>cycle switch{"daily"=>start.AddDays(index),"alternate-days"=>start.AddDays(index*2),"weekly"=>start.AddDays(index*7),"monthly"=>AddMonth(start,index),"quarterly"=>AddMonth(start,index*3),"six-monthly"=>AddMonth(start,index*6),"yearly"=>AddMonth(start,index*12),_=>start};
 public static IEnumerable<(DateOnly Start,DateOnly End)> Periods(JsonObject c){var start=J.Day(J.S(c,"start"));var end=J.Day(J.S(c,"end"));string cycle=J.S(c,"cycle");for(int i=0;i<4000;i++){var from=At(start,cycle,i);if(from>end)yield break;var to=At(start,cycle,i+1).AddDays(-1);yield return(from,to>end?end:to);}}
 public static string Date(DateOnly d)=>d.ToString("yyyy-MM-dd",CultureInfo.InvariantCulture);
 public static List<string> Staff(JsonObject p){var ids=p["amc"]?["staff"] is JsonArray a?a.Select(x=>x?.ToString()??"").Where(x=>x!="").Distinct().ToList():[];if(ids.Count==0&&J.S(p,"lead")!="")ids.Add(J.S(p,"lead"));return ids;}
 public static void Validate(Snapshot state,JsonObject p,JsonObject? old){bool changed=!JsonNode.DeepEquals(p["amc"],old?["amc"]);if(p["amc"] is not JsonObject c){J.Require(ActivityTypes.Id(p,"stageType")!="amc"||old is not null&&ActivityTypes.Id(old,"stageType")=="amc","Enter AMC contract details",400);return;}J.Require(J.ContainsAll(p["amcHistory"],old?["amcHistory"]),"AMC contract history cannot be rewritten",400);if(!changed)return;
 J.Require(System.Text.RegularExpressions.Regex.IsMatch(J.S(c,"id"),"^[A-Za-z0-9_-]{1,60}$")&&Cycles.Contains(J.S(c,"cycle")),"Invalid AMC contract ID or cycle",400);var start=J.Day(J.S(c,"start"));var end=J.Day(J.S(c,"end"));J.Require(end>=start&&end<=start.AddYears(10),"AMC dates must be ordered and within ten years",400);J.Require(J.N(c,"visits") is >=1 and <=366&&decimal.Truncate(J.N(c,"visits"))==J.N(c,"visits")&&J.N(c,"hours") is >=0.25m and <=12,"AMC requires 1–366 visits per cycle and 0.25–12 hours per visit",400);J.Minute(J.S(c,"preferredStart"));var staff=Staff(p);J.Require(c["staff"] is JsonArray roster&&roster.Count==staff.Count&&staff.Count<=100,"Select distinct AMC attendees",400);J.Require(staff.Count>0&&staff.All(id=>state.Members.TryGetValue(id,out var m)&&J.B(m,"active",true)),"Choose active AMC attendees",400);if(J.S(c,"activityId")!="")J.Require(J.A(state.Settings,"activityMaster").Any(a=>J.S(a,"id")==J.S(c,"activityId")&&ActivityTypes.Id(a)=="amc"&&J.B(a,"active",true)),"Choose an active AMC activity",400);J.Require(J.ContainsAll(p["amcHistory"],old?["amcHistory"]),"AMC contract history cannot be rewritten",400);
 }
 public static void ValidateAllocation(Snapshot state,JsonObject task,JsonObject row,JsonObject? old){if(row["countsAsAmcVisit"] is {} marked)J.Require(marked is JsonValue mv&&mv.TryGetValue<bool>(out _),"AMC visit marking must be Yes/No",400);string[] fields=["amcVisitId","amcContractId","amcCycleStart","amcDueDate"];if(old is not null){J.Require(fields.All(k=>J.S(row,k)==J.S(old,k)),"Saved AMC visit references cannot be changed",400);return;}if(J.S(row,"amcVisitId")=="")return;var p=state.Records.GetValueOrDefault("project:"+J.S(task,"project"));J.Require(p?["amc"] is JsonObject,"AMC contract required for a suggested visit",400);var c=p!["amc"]!.AsObject();J.Require(J.S(row,"amcContractId")==J.S(c,"id")&&ActivityTypes.Id(task)=="amc","AMC suggestion belongs to another contract",400);var cycle=Periods(c).FirstOrDefault(x=>Date(x.Start)==J.S(row,"amcCycleStart"));J.Require(cycle.Start!=default&&J.Day(J.S(row,"date"))>=cycle.Start&&J.Day(J.S(row,"date"))<=cycle.End,"Create AMC suggestions within their contract cycle",400);int visits=(int)J.N(c,"visits");bool valid=false;for(int i=0;i<visits;i++){string id=J.S(p,"id")+"/"+J.S(c,"id")+"/"+Date(cycle.Start)+"/"+i;if(J.S(row,"amcVisitId")==id&&J.S(row,"amcDueDate")==Date(cycle.Start.AddDays(i*(cycle.End.DayNumber-cycle.Start.DayNumber+1)/visits)))valid=true;}J.Require(valid,"Invalid AMC visit reference or due date",400);}
 public static decimal Hours(JsonObject a,bool actual){if(a[actual?"actualHours":"plannedHours"] is not null)return J.N(a,actual?"actualHours":"plannedHours");string s=J.S(a,actual?"actualStartTime":"plannedStartTime"),e=J.S(a,actual?"actualEndTime":"plannedEndTime");if(s!=""&&e!="")return Math.Max(0,Math.Round((J.Minute(e)-J.Minute(s)-J.N(a,actual?"actualBreakMinutes":"plannedBreakMinutes"))/60m,2));return actual?J.N(a,"deliveredUnits")*4:0;}
 public static string Key(JsonObject a,bool actual){if(J.S(a,"amcVisitId")!="")return J.S(a,"amcVisitId");if(J.S(a,"teamGroupId")!="")return J.S(a,"teamGroupId");if(a["plannedHours"] is not null)return "hours-"+J.S(a,"id");return (actual?(J.S(a,"actualWorkDate")!=""?J.S(a,"actualWorkDate"):J.S(a,"date")):J.S(a,"date"))+"|"+J.S(a,"plannedStartTime")+"|"+J.S(a,"plannedEndTime");}
 public static JsonObject Summary(Snapshot state,JsonObject p,DateOnly week,DateOnly today){var result=new JsonObject{["projectId"]=J.S(p,"id"),["projectCode"]=J.S(p,"code"),["projectName"]=J.S(p,"name"),["configured"]=p["amc"] is JsonObject,["periods"]=new JsonArray(),["slots"]=new JsonArray()};if(p["amc"] is not JsonObject c)return result;result["contract"]=c.DeepClone();var staff=Staff(p);var rows=state.Records.Where(x=>x.Key.StartsWith("task:")&&J.S(x.Value,"project")==J.S(p,"id")&&ActivityTypes.Id(x.Value)=="amc").SelectMany(x=>J.A(x.Value,"allocations")).Where(a=>J.S(a,"workMode")=="Onsite"&&(J.S(a,"amcContractId")==""||J.S(a,"amcContractId")==J.S(c,"id"))).ToList();int required=(int)J.N(c,"visits"),overdue=0;decimal target=J.N(c,"hours");DateOnly weekEnd=week.AddDays(6);var periodArray=result["periods"]!.AsArray();var slots=result["slots"]!.AsArray();
 foreach(var (from,to) in Periods(c)){if(from>weekEnd&&from>today)break;var dateFrom=Date(from);var dateTo=Date(to);bool InDate(string date)=>string.CompareOrdinal(date,dateFrom)>=0&&string.CompareOrdinal(date,dateTo)<=0;bool CorrectCycle(JsonObject a)=>J.S(a,"amcCycleStart")==""||J.S(a,"amcCycleStart")==dateFrom;
 var plans=rows.Where(a=>InDate(J.S(a,"date"))&&CorrectCycle(a)).GroupBy(a=>Key(a,false)).OrderBy(g=>J.S(g.First(),"date")+J.S(g.First(),"plannedStartTime")).ToList();var actuals=rows.Where(a=>J.B(a,"countsAsAmcVisit",true)&&Hours(a,true)>0&&InDate(J.S(a,"actualWorkDate")!=""?J.S(a,"actualWorkDate"):J.S(a,"date"))&&CorrectCycle(a)).GroupBy(a=>Key(a,true)).ToList();int delivered=actuals.Count(g=>g.Max(a=>Hours(a,true))>=target&&staff.All(id=>g.Any(a=>J.S(a,"assignee")==id))),scheduled=plans.Count(g=>g.Max(a=>Hours(a,false))>=target&&staff.All(id=>g.Any(a=>J.S(a,"assignee")==id&&Hours(a,false)>=target)));decimal actualHours=actuals.Sum(g=>g.Max(a=>Hours(a,true))),plannedHours=plans.Sum(g=>g.Max(a=>Hours(a,false)));bool closed=to<today;var period=new JsonObject{["start"]=dateFrom,["end"]=dateTo,["requiredVisits"]=required,["requiredHours"]=required*target,["attendedVisits"]=actuals.Count,["qualifiedVisits"]=delivered,["actualHours"]=actualHours,["scheduledVisits"]=scheduled,["plannedHours"]=plannedHours,["visitsGap"]=Math.Max(0,required-delivered),["hoursGap"]=Math.Max(0,required*target-actualHours),["closed"]=closed};if(closed&&(delivered<required||actualHours<required*target))overdue++;periodArray.Add(period);
 if(to<week||from>weekEnd)continue;var used=new HashSet<string>();for(int i=0;i<required;i++){string slotId=J.S(p,"id")+"/"+J.S(c,"id")+"/"+dateFrom+"/"+i;var due=from.AddDays(i*(to.DayNumber-from.DayNumber+1)/required);var matched=plans.FirstOrDefault(g=>g.Key==slotId)??plans.FirstOrDefault(g=>!used.Contains(g.Key)&&!g.Any(a=>J.S(a,"amcVisitId")!=""));if(matched is not null)used.Add(matched.Key);var linked=rows.Where(a=>J.S(a,"amcVisitId")==slotId).ToList();var assigned=matched?.ToList()??linked;var missing=staff.Where(id=>!assigned.Any(a=>J.S(a,"assignee")==id&&InDate(J.S(a,"date"))&&Hours(a,false)>=target)).ToList();if(due>weekEnd&&assigned.Count==0)continue;var actual=actuals.FirstOrDefault(g=>g.Key==(matched?.Key??slotId));bool fulfilled=delivered>=required||actual is not null&&actual.Max(a=>Hours(a,true))>=target&&staff.All(id=>actual.Any(a=>J.S(a,"assignee")==id));var first=assigned.FirstOrDefault();slots.Add(new JsonObject{["id"]=slotId,["projectId"]=J.S(p,"id"),["contractId"]=J.S(c,"id"),["cycleStart"]=dateFrom,["cycleEnd"]=dateTo,["dueDate"]=Date(due),["hours"]=target,["staff"]=new JsonArray(staff.Select(id=>(JsonNode)JsonValue.Create(id)!).ToArray()),["missingStaff"]=new JsonArray(missing.Select(id=>(JsonNode)JsonValue.Create(id)!).ToArray()),["fulfilled"]=fulfilled,["plannedDate"]=first is null?"":J.S(first,"date"),["plannedStart"]=first is null?"":J.S(first,"plannedStartTime"),["plannedEnd"]=first is null?"":J.S(first,"plannedEndTime"),["linked"]=assigned.Count>0,["outsideCycle"]=assigned.Any(a=>!InDate(J.S(a,"date")))});}
 }
 result["overdueCycles"]=overdue;result["weekFrom"]=Date(week);result["weekTo"]=Date(weekEnd);return result;
 }
 public static JsonObject Report(Snapshot state,Policy policy,DateOnly week){J.Require(policy.Flag("viewAmcCompliance"),"AMC monitoring permission required");return new JsonObject{["asOf"]=Date(J.Today),["week"]=Date(week),["projects"]=new JsonArray(state.Records.Where(x=>x.Key.StartsWith("project:")&&ActivityTypes.Id(x.Value,"stageType")=="amc"&&policy.ProjectScope(J.S(x.Value,"id"))).Select(x=>(JsonNode)Summary(state,x.Value,week,J.Today)).ToArray())};}
}
